def sigma(n):
    """Calculates the sum of divisors sigma(n)."""
    if n <= 0:
        return 0
    total = 1
    n_copy = n
    i = 2
    while i * i <= n_copy:
        if n_copy % i == 0:
            p = i
            count = 0
            while n_copy % p == 0:
                count += 1
                n_copy //= p
            # Sum of powers: (p^(count+1) - 1) / (p - 1)
            total *= (p**(count + 1) - 1) // (p - 1)
        i += 1
    if n_copy > 1:
        # Remaining factor is prime
        total *= (n_copy + 1)
    return total

